  "why_it_matters": [
    {
      "text": "Mistral is pitching ML4 as an alternative to closed US models that can be withdrawn or that refuse security work, and to Chinese open models. It positions the model as a sovereignty play for Europe.",
      "ids": [
        "F8",
        "F9",
        "F10"
      ]
    },
