reporter.raw:
{
  "single_story": {
    "yes": true,
    "note": "All sources cover the same Google change to Gemini model access starting Oct. 9, 2026."
  },
  "the_news": {
    "text": "Starting Oct. 9, 2026, Google will limit Gemini app users without a paid Google AI plan to the Flash-Lite model (losing Flash and Pro), and AI Plus subscribers will also lose Pro on a date Google will email them; Pro will need AI Pro ($19.99/month) or Ultra. [CLAIM: Google says, via its support page as reported by 9to5Google, PCMag, Engadget]",
    "ids": [
      "F1",
      "F2",
      "F3",
      "F4"
    ]
  },
  "why_it_matters": [
    {
      "text": "Gemini's free tier shrinks to one model and the cheapest paid tier loses the top model, so anyone who relies on Pro (coding, studying, large files) must pay about $19.99/month to keep it.",
      "ids": [
        "F1",
        "F3",
        "F6"
      ]
    },
    {
      "text": "It is the second time this year Google has overhauled its AI plans, following a compute-based usage change in May; PCMag links the timing to rising storage and component costs, but this is PCMag's suggestion ('potentially'), not a Google statement.",
      "ids": [
        "F10",
        "B1"
      ]
    }
  ],
  "facts": [
    {
      "id": "F1",
      "text": "[CLAIM: Google says, via an updated support document] Gemini app users without a Google AI subscription will be limited to the (3.5) Flash-Lite model, and from Oct. 9 will no longer be able to access (3.6) Flash or (3.1) Pro.",
      "sources": [
        "9to5Google",
        "PCMag",
        "Engadget"
      ],
      "claim_by": "Google (support page)",
      "notes": [
        "Independent reporters relay Google's support page; no independent party confirmed or questioned the change. No Google comment beyond the support page was found.",
        "9to5Google discovered the support-page update; PCMag and Engadget follow it."
      ]
    },
    {
      "id": "F2",
      "text": "[CLAIM: Google says] Google AI Plus subscribers will be limited to Flash-Lite and Flash, with Pro no longer available, and will 'receive an email that explains when these changes will take effect.'",
      "sources": [
        "9to5Google",
        "PCMag",
        "Yahoo Creators"
      ],
      "claim_by": "Google (support page)",
      "notes": [
        "Yahoo Creators says Plus users' date may differ from Oct. 9 and advises not to upgrade before reading the email (writer's advice)."
      ]
    },
    {
      "id": "F3",
      "text": "Pro will require AI Pro or AI Ultra; AI Pro and AI Ultra have no regressions and all three models remain available there.",
      "sources": [
        "9to5Google",
        "Yahoo Creators",
        "PCMag"
      ],
      "claim_by": null,
      "notes": []
    },
    {
      "id": "F4",
      "text": "Today free users can pick among Flash-Lite, Flash and Pro in a drop-down menu in the app or next to the text box on desktop; after the change, free requests will all use Flash-Lite.",
      "sources": [
        "Engadget",
        "Yahoo Creators"
      ],
      "claim_by": null,
      "notes": []
    },
    {
      "id": "F5",
      "text": "Google is adding 'low', 'medium' and 'high' effort levels for each available model; higher levels give more thorough answers but use more of the user's limit.",
      "sources": [
        "9to5Google",
        "PCMag",
        "Engadget"
      ],
      "claim_by": "Google (support page)",
      "notes": [
        "9to5Google says this looks to be coming in October; PCMag says 'soon'."
      ]
    },
    {
      "id": "F6",
      "text": "A Plus subscriber who wants to keep Pro would pay roughly $15 more per month, or $180 a year, at current prices (Yahoo's calculation from $4.99 vs $19.99).",
      "sources": [
        "Yahoo Creators"
      ],
      "claim_by": null,
      "notes": [
        "Arithmetic from listed prices by the Yahoo writer."
      ]
    },
    {
      "id": "F7",
      "text": "AI Pro subscribers will get the Deep Think option ('maximum parallel reasoning'), currently only on the $99.99 and $199.99/month plans, per 9to5Google; Engadget and UA.news say Deep Think goes to AI Ultra subscribers.",
      "sources": [
        "9to5Google",
        "Engadget"
      ],
      "claim_by": null,
      "notes": [
        "Sources disagree: 9to5Google says AI Pro gets Deep Think (headline: 'AI Pro adding Deep Think'); Engadget says AI Ultra subscribers get Deep Think."
      ]
    },
    {
      "id": "F8",
      "text": "Eligible U.S. college students can get one year of AI Pro free, redeemable through Dec. 31, 2026; it requires a valid payment method and charges $19.99/month afterward unless canceled.",
      "sources": [
        "Yahoo Creators"
      ],
      "claim_by": null,
      "notes": [
        "PCMag also says students remain eligible for a year of AI Pro free."
      ]
    },
    {
      "id": "F9",
      "text": "Google's own support page describes Flash-Lite as built for speed and everyday tasks like summarization and brainstorming, Flash as balancing speed and reasoning, and Pro as its most advanced model for complex math and coding.",
      "sources": [
        "Google Gemini Help (support page)",
        "Yahoo Creators"
      ],
      "claim_by": null,
      "notes": [
        "The support page version opened (cached/older) did not yet show the new Oct. 9 restrictions; its model-access table showed Yes for all models on all plans."
      ]
    },
    {
      "id": "F10",
      "text": "PCMag says this is the second time Google has overhauled its AI plans this year and that the changes come as storage and component costs continue to rise, 'potentially' affecting AI infrastructure spending.",
      "sources": [
        "PCMag"
      ],
      "claim_by": "PCMag",
      "notes": [
        "Google has not stated a cost reason in the sources opened."
      ]
    },
    {
      "id": "F11",
      "text": "9to5Google says it is not clear where the new Gemini 4 Argon will fit; Engadget says AI Ultra subscribers will get Argon when it rolls out publicly, and it is currently available only to Google's Fairwind Program members (governments and trusted partners).",
      "sources": [
        "9to5Google",
        "Engadget"
      ],
      "claim_by": null,
      "notes": []
    }
  ],
  "background": [
